        {
            item=trim($1)
            result=trim($3)
            if (item == "" || result == "") next
            if (item ~ /^FINDING_[0-9A-Za-z_]+$/) {
                if (result == "accepted") accepted++
                else if (result == "rejected") rejected++
                else if (result == "neutral") neutral++
                else if (result == "exonerated") exonerated++
            } else if (item ~ /^OOS_[0-9A-Za-z_]+$/) {
                if (result == "accepted") oos_accepted++
                else oos_rejected++
            }
        }
        END { printf "%d\t%d\t%d\t%d\t%d\t%d\n", accepted+0, rejected+0, neutral+0, exonerated+0, oos_accepted+0, oos_rejected+0 }
    ' "$file" 2>/dev/null || printf '0\t0\t0\t0\t0\t0\n'
}

_counts_all_zero() {
    [[ "${1:-}" == $'0\t0\t0\t0\t0\t0' ]]
}

_tsv_has_data_rows() {
    local file="$1"
    awk 'NR > 1 && NF > 0 { found = 1; exit } END { exit(found ? 0 : 1) }' "$file" 2>/dev/null
}

_extract_oos_block() {
    local round_dir="$1" oos_id="$2"
    python3 - "$round_dir" "$oos_id" <<'PY'
import re
import sys
from pathlib import Path

round_dir = Path(sys.argv[1])
oos_id = sys.argv[2]
pattern = re.compile(rf"(?ms)^### {re.escape(oos_id)}:.*?(?=^### |\Z)")

for name in ("findings-oos.md", "findings.md", "oos.md", "findings-in-scope.md"):
    path = round_dir / name
    if not path.is_file():
        continue
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        continue
    match = pattern.search(text)
    if match:
        sys.stdout.write(match.group(0))
        raise SystemExit(0)
raise SystemExit(1)
PY
}

_adjust_security_oos_counts() {
    local round_dir="$1" source="$2"
    local id result block_file
    case "$source" in
        md)
            while IFS=$'\t' read -r id result || [[ -n "$id" ]]; do
                [[ -n "$id" ]] || continue
                block_file="$(mktemp "${round_dir}/.oos-sec.XXXXXX")"
                if _extract_oos_block "$round_dir" "$id" >"$block_file" 2>/dev/null \
                    && [[ -s "$block_file" ]]; then
                    if python3 "$CLI" voting is-security-block "$block_file" 2>/dev/null; then
                        case "$result" in
                            accepted) OOS_ACCEPTED_COUNT=$((OOS_ACCEPTED_COUNT - 1)) ;;
                            *) OOS_REJECTED_COUNT=$((OOS_REJECTED_COUNT - 1)) ;;
                        esac
                    fi
                fi
                rm -f "$block_file"
            done < <(awk -F'|' '
                function trim(s) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s }
                /^## Findings/ { in_findings = 1; next }
                /^## / && in_findings { in_findings = 0 }
                in_findings && NF >= 4 {
                    item = trim($2)
                    result = trim($(NF-1))
                    if (result == "" || result ~ /^-+$/) {
                        result = trim($(NF-2))
                    }
                    if (item ~ /^OOS_[0-9A-Za-z_]+$/ && result != "") {
                        print item "\t" result
                    }
                }
            ' "$round_dir/voting-tally.md" 2>/dev/null)
            ;;
        tsv)
            while IFS=$'\t' read -r id result || [[ -n "$id" ]]; do
                [[ -n "$id" ]] || continue
                [[ "$id" =~ ^OOS_[0-9A-Za-z_]+$ ]] || continue
                [[ -n "$result" ]] || continue
                block_file="$(mktemp "${round_dir}/.oos-sec.XXXXXX")"
                if _extract_oos_block "$round_dir" "$id" >"$block_file" 2>/dev/null \
                    && [[ -s "$block_file" ]]; then
                    if python3 "$CLI" voting is-security-block "$block_file" 2>/dev/null; then
                        case "$result" in
                            accepted) OOS_ACCEPTED_COUNT=$((OOS_ACCEPTED_COUNT - 1)) ;;
                            *) OOS_REJECTED_COUNT=$((OOS_REJECTED_COUNT - 1)) ;;
                        esac
                    fi
                fi
                rm -f "$block_file"
            done < <(awk -F'\t' 'NR > 1 && $1 ~ /^OOS_/ { print $1 "\t" $3 }' \
                "$round_dir/findings-classification.tsv" 2>/dev/null)
            ;;
    esac
    if (( OOS_ACCEPTED_COUNT < 0 )); then OOS_ACCEPTED_COUNT=0; fi
    if (( OOS_REJECTED_COUNT < 0 )); then OOS_REJECTED_COUNT=0; fi
}

_counts=""
_count_source=""
_md_counts=""
_tsv_counts=""
if [[ -f "$ROUND_DIR/voting-tally.md" ]]; then
    _md_counts="$(_parse_tally_md "$ROUND_DIR/voting-tally.md")"
    _counts="$_md_counts"
    _count_source=md
fi
if [[ -f "$ROUND_DIR/findings-classification.tsv" ]]; then
    _tsv_counts="$(_parse_classification_tsv "$ROUND_DIR/findings-classification.tsv")"
    if [[ -z "$_counts" ]]; then
        _counts="$_tsv_counts"
        _count_source=tsv
    elif _counts_all_zero "$_md_counts" && _tsv_has_data_rows "$ROUND_DIR/findings-classification.tsv"; then
        _counts="$_tsv_counts"
        _count_source=tsv
    fi
fi
[[ -n "$_counts" ]] || _counts=$'0\t0\t0\t0\t0\t0'
IFS=$'\t' read -r ACCEPTED_COUNT REJECTED_COUNT NEUTRAL_COUNT EXONERATED_COUNT OOS_ACCEPTED_COUNT OOS_REJECTED_COUNT <<EOF_COUNTS
$_counts
EOF_COUNTS
for _v in ACCEPTED_COUNT REJECTED_COUNT NEUTRAL_COUNT EXONERATED_COUNT OOS_ACCEPTED_COUNT OOS_REJECTED_COUNT; do
    case "${!_v:-}" in ''|*[!0-9]*) printf -v "$_v" '%s' 0 ;; esac
done
if [[ -n "$_count_source" ]]; then
    _adjust_security_oos_counts "$ROUND_DIR" "$_count_source"
fi

_panel_tmp="$ROUND_DIR/panel-manifest.ndjson.tmp"
_meta_tmp="$ROUND_DIR/round-meta.json.tmp"
trap 'rm -f "$_panel_tmp" "$_meta_tmp"' EXIT
_panel_count=0
# Prefer per-round copy; fall back to session-root copy (concise snapshots no longer
# stage plan-review-slots.ndjson into round dirs).
_slots_src="$ROUND_DIR/plan-review-slots.ndjson"
if [[ ! -f "$_slots_src" ]]; then
    _design_root=$(dirname "$(dirname "$ROUND_DIR")")
    _slots_src="$_design_root/plan-review-slots.ndjson"
fi
if command -v python3 >/dev/null 2>&1; then
    _panel_count=$(python3 - "$_slots_src" "$_panel_tmp" <<'PY' || printf '0'
import json
import sys
from pathlib import Path

src = Path(sys.argv[1])
out = Path(sys.argv[2])
count = 0
with out.open("w", encoding="utf-8") as dst:
    try:
        lines = src.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        lines = []
    for line in lines:
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        slot = str(obj.get("slot") or "")
        tool = str(obj.get("tool") or "")
        output = str(obj.get("output") or "")
        if not (slot or tool or output):
            continue
        dst.write(json.dumps({"slot": slot, "tool": tool, "output": output}, separators=(",", ":")) + "\n")
        count += 1
print(count)
PY
)
else
    : >"$_panel_tmp"
fi
case "$_panel_count" in ''|*[!0-9]*) _panel_count=0 ;; esac
mv -f "$_panel_tmp" "$ROUND_DIR/panel-manifest.ndjson" 2>/dev/null || true

_collect_failures=0
if [[ -f "$ROUND_DIR/round-summary.env" ]]; then
    _collect_failures=$(awk -F= '$1 == "COLLECT_FAILURE_COUNT" { print $2; exit }' "$ROUND_DIR/round-summary.env" 2>/dev/null || printf '0')
fi
case "$_collect_failures" in ''|*[!0-9]*) _collect_failures=0 ;; esac
_collector=""
_i=1
while [[ "$_i" -le "$_collect_failures" ]]; do
    _record=$(printf 'TOOL=unknown\nSTATUS=FAILED\nREVIEWER_FILE=collector-failure-%s.txt\n' "$_i")
    if [[ -n "$_collector" ]]; then
        _collector="$_collector"$'\n\n'"$_record"
    else
        _collector="$_record"
    fi
    _i=$((_i + 1))
done

# Read revise outcome from round-N/revise/revise.env when present (written by
# revise-plan-with-waterfall.sh after the revise step runs for this round).
_revise_status=""
_revise_tier=""
_revise_env="$ROUND_DIR/revise/revise.env"
if [[ -f "$_revise_env" ]]; then
    while IFS= read -r _rline || [[ -n "$_rline" ]]; do
        case "$_rline" in
            REVISE_STATUS=*) _revise_status="${_rline#REVISE_STATUS=}" ;;
            REVISE_TIER=*)   _revise_tier="${_rline#REVISE_TIER=}" ;;
        esac
    done < "$_revise_env"
fi

if command -v jq >/dev/null 2>&1; then
    jq -n \
        --arg accepted "$ACCEPTED_COUNT" \
        --arg rejected "$REJECTED_COUNT" \
        --arg exonerated "$EXONERATED_COUNT" \
        --arg neutral "$NEUTRAL_COUNT" \
        --arg oos_accepted "$OOS_ACCEPTED_COUNT" \
        --arg oos_rejected "$OOS_REJECTED_COUNT" \
        --arg panel_count "$_panel_count" \
        --arg collector "$_collector" \
        --arg revise_status "$_revise_status" \
        --arg revise_tier "$_revise_tier" \
        '{tally:{ACCEPTED_COUNT:$accepted,REJECTED_COUNT:$rejected,EXONERATED_COUNT:$exonerated,NEUTRAL_COUNT:$neutral,OOS_ACCEPTED_COUNT:$oos_accepted,OOS_REJECTED_COUNT:$oos_rejected},summary:{panel:{total_slot_count:($panel_count|tonumber)}},collector:$collector,revise:{status:(if $revise_status=="" then null else $revise_status end),tier:(if $revise_tier=="" then null else $revise_tier end)}}' \
        >"$_meta_tmp" 2>/dev/null || : >"$_meta_tmp"
fi

if [[ ! -s "$_meta_tmp" ]]; then
    if command -v python3 >/dev/null 2>&1; then
        python3 - "$ACCEPTED_COUNT" "$REJECTED_COUNT" "$EXONERATED_COUNT" "$NEUTRAL_COUNT" "$OOS_ACCEPTED_COUNT" "$OOS_REJECTED_COUNT" "$_panel_count" "$_collector" "$_revise_status" "$_revise_tier" "$_meta_tmp" <<'PY' || : >"$_meta_tmp"
import json
import sys
accepted, rejected, exonerated, neutral, oos_accepted, oos_rejected, panel_count, collector, revise_status, revise_tier, out = sys.argv[1:12]
obj = {
    "tally": {
        "ACCEPTED_COUNT": accepted,
        "REJECTED_COUNT": rejected,
        "EXONERATED_COUNT": exonerated,
        "NEUTRAL_COUNT": neutral,
        "OOS_ACCEPTED_COUNT": oos_accepted,
        "OOS_REJECTED_COUNT": oos_rejected,
    },
    "summary": {"panel": {"total_slot_count": int(panel_count or 0)}},
    "collector": collector,
    "revise": {
        "status": revise_status or None,
        "tier": revise_tier or None,
    },
}
with open(out, "w", encoding="utf-8") as fh:
    json.dump(obj, fh, indent=2)
    fh.write("\n")
PY
    fi
fi

if [[ -s "$_meta_tmp" ]]; then
    mv -f "$_meta_tmp" "$ROUND_DIR/round-meta.json" 2>/dev/null || true
else
    rm -f "$_meta_tmp" 2>/dev/null || true
fi
exit 0
